import { FlyingPosters } from "solen-design/react";

const items = [
  { image: "/posters/one.jpg" },
  { image: "/posters/two.jpg" },
  { image: "/posters/three.jpg" },
  { image: "/posters/four.jpg" }
];

<FlyingPosters
  items={items}
  planeWidth={320}
  planeHeight={320}
  distortion={3}
  scrollEase={0.01}
  cameraFov={45}
  cameraZ={20}
  columns={1}
  columnGap={40}
  alternate={true}
  radius={0}
